CREATE TABLE noctis_v2.ai_configs(revision bigint PRIMARY KEY, body jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.ai_secrets(config_revision bigint NOT NULL REFERENCES noctis_v2.ai_configs(revision),connection_id text NOT NULL,key_id text NOT NULL,nonce bytea NOT NULL,ciphertext bytea NOT NULL,PRIMARY KEY(config_revision,connection_id));
CREATE TABLE noctis_v2.ai_jobs(id uuid PRIMARY KEY,actor text NOT NULL,request_id text NOT NULL,function_id text NOT NULL,input jsonb NOT NULL,snapshot jsonb NOT NULL,config_revision bigint NOT NULL REFERENCES noctis_v2.ai_configs(revision),state text NOT NULL CHECK(state IN ('queued','running','retry_wait','budget_blocked','dependency_blocked','succeeded','failed','cancelled')),fence bigint NOT NULL DEFAULT 0,lease_until timestamptz,retry_at timestamptz,attempts integer NOT NULL DEFAULT 0,result jsonb,error_code text,cache_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(actor,request_id));
CREATE INDEX ai_jobs_queue ON noctis_v2.ai_jobs(state,retry_at,lease_until);
CREATE TABLE noctis_v2.ai_attempts(id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES noctis_v2.ai_jobs(id),fence bigint NOT NULL,config_revision bigint NOT NULL,function_id text NOT NULL,functions jsonb NOT NULL,binding jsonb NOT NULL,connection jsonb NOT NULL,maximum_units bigint NOT NULL CHECK(maximum_units>=0),actual_units bigint,exposure_units bigint NOT NULL CHECK(exposure_units>=0),state text NOT NULL CHECK(state IN ('reserved','sent','settled','uncertain','released')),requested_model text NOT NULL,declared_model text NOT NULL DEFAULT 'unknown',usage jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX ai_attempts_period ON noctis_v2.ai_attempts(created_at,function_id);
CREATE TABLE noctis_v2.ai_products(job_id uuid PRIMARY KEY REFERENCES noctis_v2.ai_jobs(id),function_id text NOT NULL,input_kind text NOT NULL,input_id text NOT NULL,input_revision text NOT NULL,dependencies jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.ai_publications(cache_key text NOT NULL,function_id text NOT NULL,job_id uuid NOT NULL REFERENCES noctis_v2.ai_jobs(id),PRIMARY KEY(cache_key,function_id));
CREATE TABLE noctis_v2.ai_query_results(id uuid PRIMARY KEY,actor text NOT NULL,plan jsonb NOT NULL,rows jsonb NOT NULL,dependencies jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.ai_attempt_jobs(attempt_id uuid NOT NULL REFERENCES noctis_v2.ai_attempts(id),job_id uuid NOT NULL REFERENCES noctis_v2.ai_jobs(id),fence bigint NOT NULL,PRIMARY KEY(attempt_id,job_id));
CREATE TABLE noctis_v2.ai_promotions(id uuid PRIMARY KEY,function_id text NOT NULL,config_revision bigint NOT NULL,dataset_version text NOT NULL,status text NOT NULL CHECK(status IN ('pending','invalidated','validated')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION noctis_v2.ai_immutable_revision() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'immutable AI revision';END$$;
CREATE TRIGGER ai_configs_immutable BEFORE UPDATE OR DELETE ON noctis_v2.ai_configs FOR EACH ROW EXECUTE FUNCTION noctis_v2.ai_immutable_revision();
CREATE TRIGGER ai_secrets_immutable BEFORE UPDATE OR DELETE ON noctis_v2.ai_secrets FOR EACH ROW EXECUTE FUNCTION noctis_v2.ai_immutable_revision();
CREATE TRIGGER ai_products_immutable BEFORE UPDATE OR DELETE ON noctis_v2.ai_products FOR EACH ROW EXECUTE FUNCTION noctis_v2.ai_immutable_revision();
